+    fn yank_current_line(&mut self) {
+        let focus = if self.left_visible {
+            self.focus
+        } else {
+            PaneFocus::Right
+        };
+        let lines = self.focus_source_lines(focus);
+        let position = self.current_visual_position(focus);
+        let text = lines.get(position.row).cloned().unwrap_or_default();
+        self.queue_yanked_text(text);
+    }
+
+    fn queue_yanked_text(&mut self, text: String) {
+        if text.is_empty() {
+            self.show_status_notice(
+                "nothing selected",
+                Duration::from_secs(STATUS_NOTICE_SECONDS),
+            );
+            return;
+        }
+
+        let char_count = text.chars().count();
+        *self.pending_clipboard.borrow_mut() = Some(text);
+        self.show_status_notice(
+            format!("yanked {char_count} chars"),
