+    fn apply_visual_selection(&self, buffer: &mut Buffer, right_content: &str) {
+        let Some(selection) = self.visual_selection.as_ref() else {
+            return;
+        };
+
+        match selection.focus {
+            PaneFocus::Left => self.apply_left_visual_selection(buffer, selection),
+            PaneFocus::Right => self.apply_right_visual_selection(buffer, selection, right_content),
+        }
+    }
+
+    fn apply_left_visual_selection(&self, buffer: &mut Buffer, selection: &VisualSelection) {
+        let layout = self.layout();
+        if layout.left_width == 0 {
+            return;
+        }
+
+        let lines = self.left_visible_lines();
+        let ranges = selection_ranges(selection, &lines, false);
+        let inner_width = usize::from(layout.left_width.saturating_sub(2).max(1));
+        let inner_height = self.pane_inner_height();
+
+        for range in ranges {
+            if range.row >= inner_height {
+                continue;
+            }
+            let y = 1 + range.row;
+            let start = range.start.min(inner_width);
+            let end = range.end.min(inner_width);
+            for column in start..end {
+                mark_reversed(buffer, 1 + column, y);
+            }
+        }
+    }
+
+    fn apply_right_visual_selection(
+        &self,
+        buffer: &mut Buffer,
+        selection: &VisualSelection,
+        right_content: &str,
+    ) {
+        let layout = self.layout();
+        let lines = right_content_lines(right_content);
+        let ranges = selection_ranges(selection, &lines, false);
+        let inner_width = usize::from(layout.right_width.saturating_sub(2).max(1));
+        let inner_height = self.pane_inner_height();
+        let base_x = usize::from(layout.left_width) + 1;
+        let base_y = 1;
+        let mut row_offsets = Vec::with_capacity(lines.len());
+        let mut offset = 0_usize;
+        for line in &lines {
+            row_offsets.push(offset);
+            offset = offset.saturating_add(visual_row_count(line, layout.right_width));
+        }
+
+        for range in ranges {
+            let Some(row_offset) = row_offsets.get(range.row).copied() else {
+                continue;
+            };
+            for column in range.start..range.end {
+                let visual_row = row_offset + (column / inner_width);
+                if visual_row >= inner_height {
+                    continue;
+                }
+                let x = base_x + (column % inner_width);
+                let y = base_y + visual_row;
+                mark_reversed(buffer, x, y);
+            }
+        }
+    }

