 fn cursor_char_count(text: &str, cursor: usize) -> usize {
     text.char_indices()
         .take_while(|(index, _)| *index < cursor)
         .count()
 }
+
+fn line_char_count(line: &str) -> usize {
+    line.chars().count()
+}
+
+fn right_content_lines(content: &str) -> Vec<String> {
+    if content.is_empty() {
+        Vec::new()
+    } else {
+        content.lines().map(ToString::to_string).collect()
+    }
+}
+
+fn selected_text(selection: &VisualSelection, lines: &[String], linewise: bool) -> String {
+    selection_ranges(selection, lines, linewise)
+        .into_iter()
+        .map(|range| char_slice(&lines[range.row], range.start, range.end))
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selection_ranges(
+    selection: &VisualSelection,
+    lines: &[String],
+    linewise: bool,
+) -> Vec<SelectionRange> {
+    if lines.is_empty() {
+        return Vec::new();
+    }
+
+    let start_row = selection.anchor.row.min(selection.cursor.row);
+    let end_row = selection
+        .anchor
+        .row
+        .max(selection.cursor.row)
+        .min(lines.len().saturating_sub(1));
+    if start_row > end_row {
+        return Vec::new();
+    }
+
+    if linewise || selection.mode == VisualSelectionMode::Line {
+        return (start_row..=end_row)
+            .map(|row| SelectionRange {
+                row,
+                start: 0,
+                end: line_char_count(&lines[row]),
+            })
+            .collect();
+    }
+
+    if selection.mode == VisualSelectionMode::Block {
+        let start_column = selection.anchor.column.min(selection.cursor.column);
+        let end_column = selection
+            .anchor
+            .column
+            .max(selection.cursor.column)
+            .saturating_add(1);
+        return (start_row..=end_row)
+            .map(|row| {
+                let line_len = line_char_count(&lines[row]);
+                SelectionRange {
+                    row,
+                    start: start_column.min(line_len),
+                    end: end_column.min(line_len),
+                }
+            })
+            .collect();
+    }
+
+    let (start, end) = ordered_visual_positions(selection.anchor, selection.cursor);
+    (start.row..=end.row.min(lines.len().saturating_sub(1)))
+        .map(|row| {
+            let line_len = line_char_count(&lines[row]);
+            let start_column = if row == start.row {
+                start.column.min(line_len)
+            } else {
+                0
+            };
+            let end_column = if row == end.row {
+                end.column.saturating_add(1).min(line_len)
+            } else {
+                line_len
+            };
+            SelectionRange {
+                row,
+                start: start_column,
+                end: end_column,
+            }
+        })
+        .collect()
+}
+
+fn ordered_visual_positions(
+    left: VisualPosition,
+    right: VisualPosition,
+) -> (VisualPosition, VisualPosition) {
+    if (left.row, left.column) <= (right.row, right.column) {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}
+
+fn char_slice(line: &str, start: usize, end: usize) -> String {
+    line.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn mark_reversed(buffer: &mut Buffer, x: usize, y: usize) {
+    if x >= usize::from(buffer.area.width) || y >= usize::from(buffer.area.height) {
+        return;
+    }
+    buffer
+        .get_mut(x.min(usize::from(u16::MAX)) as u16, y.min(usize::from(u16::MAX)) as u16)
+        .modifier
+        .insert(Modifier::REVERSED);
+}
+
+fn osc52_clipboard_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] =
+        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut output = String::with_capacity(bytes.len().saturating_add(2) / 3 * 4);
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = *chunk.get(1).unwrap_or(&0);
+        let third = *chunk.get(2).unwrap_or(&0);
+        output.push(TABLE[usize::from(first >> 2)] as char);
+        output.push(TABLE[usize::from(((first & 0b0000_0011) << 4) | (second >> 4))] as char);
+        if chunk.len() > 1 {
+            output.push(
+                TABLE[usize::from(((second & 0b0000_1111) << 2) | (third >> 6))] as char,
+            );
+        } else {
+            output.push('=');
+        }
+        if chunk.len() > 2 {
+            output.push(TABLE[usize::from(third & 0b0011_1111)] as char);
+        } else {
+            output.push('=');
+        }
+    }
+    output
+}

